pub(super) fn handle_key_event_with_slash_popup(
        &mut self,
        key_event: KeyEvent,
    ) -> (InputResult, bool) {
        if self.handle_empty_prompt_shortcut(&key_event) {
            return (InputResult::None, true);
        }
        if key_event.code == KeyCode::Esc {
            // Always dismiss the popup without changing the draft.
            let text = self.current_text();
            let first_line = text.lines().next().unwrap_or("");
            self.popups.dismissed_command_token =
                command_popup_filter_text(first_line, /*cursor*/ 0);
            self.popups.active = ActivePopup::None;
            return (InputResult::None, true);
        }
        self.footer.mode = reset_mode_after_activity(self.footer.mode);
        let current_text = self.current_text();
        let current_cursor = self.current_cursor();
        let first_line = current_text.lines().next().unwrap_or("");
        let ActivePopup::Command(popup) = &mut self.popups.active else {
            unreachable!();
        };

        match key_event {
            KeyEvent {
                code: KeyCode::Up, ..
            }
            | KeyEvent {
                code: KeyCode::Char('p'),
                modifiers: KeyModifiers::CONTROL,
                ..
            } => {
                popup.move_up();
                (InputResult::None, true)
            }
            KeyEvent {
                code: KeyCode::Down,
                ..
            }
            | KeyEvent {
                code: KeyCode::Char('n'),
                modifiers: KeyModifiers::CONTROL,
                ..
            } => {
                popup.move_down();
                (InputResult::None, true)
            }
            KeyEvent {
                code: KeyCode::Tab, ..
            } => {
                // Ensure popup filtering/selection reflects the latest composer text
                // before applying completion.
                let filter_text = command_popup_filter_text(first_line, current_cursor)
                    .unwrap_or_else(|| first_line.to_owned());
                popup.on_composer_text_change(filter_text);
                let has_visible_items = !popup.filtered_items().is_empty();
                let selected_item = popup.selected_item();
                let has_selectable_item = selected_item.is_some();
                if let Some(selected_cmd) = selected_item {
                    if selected_command_dispatches_immediately_on_tab(&selected_cmd)
                        && let CommandItem::Builtin(cmd) = &selected_cmd
                    {
                        self.stage_selected_slash_command_history(&selected_cmd);
                        self.draft.textarea.set_text_clearing_elements("");
                        self.draft.prompt_prefix = PromptPrefix::None;
                        return (InputResult::Command(*cmd), true);
                    }

                    if self
                        .complete_selected_slash_command_preserving_existing_draft_tail_as_inline_args(
                            &selected_cmd,
                        )
                    {
                        return (InputResult::None, true);
                    }

                    if let Some(completed_text) =
                        selected_command_completion(first_line, &selected_cmd)
                    {
                        self.set_canonical_text_clearing_elements(completed_text);
                        if !self.draft.textarea.text().is_empty() {
                            self.draft
                                .textarea
                                .set_cursor(self.draft.textarea.text().len());
                        }
                        return (InputResult::None, true);
                    }
                }
                if has_visible_items && !has_selectable_item {
                    return (InputResult::None, true);
                }
                if self.is_task_running {
                    return self.handle_submission(/*should_queue*/ true);
                }
                (InputResult::None, true)
            }
            KeyEvent {
                code: KeyCode::Char('/'),
                modifiers: KeyModifiers::NONE,
                ..
            } => {
                // Treat "/" as accepting the highlighted command as text completion
                // while the slash-command popup is active.
                let filter_text = command_popup_filter_text(first_line, current_cursor)
                    .unwrap_or_else(|| first_line.to_owned());
                popup.on_composer_text_change(filter_text);
                if let Some(selected_cmd) = popup.selected_item() {
                    if self
                        .complete_selected_slash_command_preserving_existing_draft_tail_as_inline_args(
                            &selected_cmd,
                        )
                    {
                        return (InputResult::None, true);
                    }

                    if let Some(completed_text) =
                        selected_command_completion(first_line, &selected_cmd)
                    {
                        self.set_canonical_text_clearing_elements(completed_text);
                    }
                    if !self.draft.textarea.text().is_empty() {
                        self.draft
                            .textarea
                            .set_cursor(self.draft.textarea.text().len());
                    }
                    return (InputResult::None, true);
                }
                self.handle_key_event_without_popup(key_event)
            }
            KeyEvent {
                code: KeyCode::Enter,
                modifiers: KeyModifiers::NONE,
                ..
            } => {
                if let Some(sel) = popup.selected_item() {
                    if self.blocks_direct_input {
                        let command_is_allowed = match &sel {
                            CommandItem::Builtin(cmd) => parse_slash_name(&current_text)
                                .is_some_and(|(_, args, _)| {
                                    parent_owned_command_is_allowed(*cmd, args)
                                }),
                            CommandItem::ServiceTier(_) => false,
                        };
                        if !command_is_allowed {
                            return (InputResult::ParentOwnedInputBlocked, true);
                        }
                    }
                    if self
                        .complete_selected_slash_command_preserving_existing_draft_tail_as_inline_args(
                            &sel,
                        )
                        && let Some(result) = self.try_dispatch_slash_command_with_args()
                    {
                        return (result, true);
                    }

                    self.stage_selected_slash_command_history(&sel);
                    if !matches!(sel, CommandItem::Builtin(cmd) if cmd.requires_dispatch_validation())
                    {
                        self.draft.textarea.set_text_clearing_elements("");
                        self.draft.prompt_prefix = PromptPrefix::None;
                    }
                    return (
                        match sel {
                            CommandItem::Builtin(cmd) => InputResult::Command(cmd),
                            CommandItem::ServiceTier(command) => {
                                InputResult::ServiceTierCommand(command)
                            }
                        },
                        true,
                    );
                }
                // Fallback to default newline handling if no command selected.
                self.handle_key_event_without_popup(key_event)
            }
            input => self.handle_input_basic(input),
        }
    }

fn complete_selected_slash_command_preserving_existing_draft_tail_as_inline_args(
        &mut self,
        selected_cmd: &CommandItem,
    ) -> bool {
        let CommandItem::Builtin(cmd) = selected_cmd else {
            return false;
        };
        if !cmd.supports_inline_args() {
            return false;
        }

        let text = self.current_text();
        let first_line_end = text.find('\n').unwrap_or(text.len());
        let cursor = self.current_cursor();
        if cursor > first_line_end || !text.starts_with('/') || !text.is_char_boundary(cursor) {
            return false;
        }

        let command_token_end = text[1..first_line_end]
            .find(char::is_whitespace)
            .map(|idx| 1 + idx)
            .unwrap_or(first_line_end);
        let typed_command_name = &text[1..command_token_end];
        let rest_after_token_is_empty = text[command_token_end..].trim().is_empty();
        if rest_after_token_is_empty && (cursor <= 1 || cursor >= command_token_end) {
            return false;
        }
        let replace_end =
            if cursor <= 1 || (typed_command_name == cmd.command() && rest_after_token_is_empty) {
                command_token_end
            } else {
                cursor
            };
        let tail = &text[replace_end..];
        let tail_starts_with_whitespace = tail.chars().next().is_some_and(char::is_whitespace);
        let selected_command_text = format!("/{}", cmd.command());
        let replacement = if tail_starts_with_whitespace {
            selected_command_text
        } else {
            format!("{selected_command_text} ")
        };

        let prefix_len = self.draft.prompt_prefix.len();
        let internal_replace_end = replace_end.saturating_sub(prefix_len);
        let ranges_to_unmark = self
            .draft
            .textarea
            .text_elements()
            .into_iter()
            .filter_map(|element| {
                let range = element.byte_range.start..element.byte_range.end;
                (range.start < internal_replace_end && internal_replace_end < range.end)
                    .then_some(range)
            })
            .collect::<Vec<_>>();
        for range in ranges_to_unmark {
            self.draft.textarea.remove_element_range(range);
        }
        self.draft
            .textarea
            .replace_range(0..internal_replace_end, &replacement[prefix_len..]);
        self.draft.prompt_prefix = PromptPrefix::Slash;
        self.draft
            .textarea
            .set_cursor(self.draft.textarea.text().len());
        true
    }

pub(super) fn sync_slash_command_elements(&mut self) {
        self.unmark_slash_command_element();
        if !self.slash_commands_enabled() {
            return;
        }
        let canonical_text = self.current_text();
        let first_line_end = canonical_text.find('\n').unwrap_or(canonical_text.len());
        let first_line = &canonical_text[..first_line_end];
        let cursor = self.current_cursor();
        let prefix_len = self.draft.prompt_prefix.len();
        let desired_range = self
            .slash_input()
            .command_element_range(first_line, cursor)
            .map(|range| 0..range.end.saturating_sub(prefix_len));
        if let Some(range) = desired_range {
            self.draft.slash_command_element_id = self.draft.textarea.add_element_range(range);
        }
    }

pub(super) fn unmark_slash_command_element(&mut self) {
        if let Some(id) = self.draft.slash_command_element_id.take() {
            self.draft.textarea.remove_element(id);
        }
    }

pub(super) fn selected_command_dispatches_immediately_on_tab(command: &CommandItem) -> bool {
    matches!(command, CommandItem::Builtin(SlashCommand::Skills))
}

pub(super) fn selected_command_completion(
    first_line: &str,
    command: &CommandItem,
) -> Option<String> {
    let selected_command_text = format!("/{}", command.command());
    (!first_line.trim_start().starts_with(&selected_command_text))
        .then(|| format!("{selected_command_text} "))
}

pub(super) fn prepared_args(prepared_text: &str) -> Option<(&str, usize)> {
    let (_, prepared_rest, prepared_rest_offset) = parse_slash_name(prepared_text)?;
    Some((prepared_rest, prepared_rest_offset))
}

pub(super) fn args_elements(
    rest: &str,
    rest_offset: usize,
    text_elements: &[TextElement],
) -> Vec<TextElement> {
    if rest.is_empty() || text_elements.is_empty() {
        return Vec::new();
    }
    text_elements
        .iter()
        .filter_map(|elem| {
            if elem.byte_range.end <= rest_offset {
                return None;
            }
            let start = elem.byte_range.start.saturating_sub(rest_offset);
            let mut end = elem.byte_range.end.saturating_sub(rest_offset);
            if start >= rest.len() {
                return None;
            }
            end = end.min(rest.len());
            (start < end).then_some(elem.map_range(|_| ByteRange { start, end }))
        })
        .collect()
}

pub(super) fn command_popup_filter_text(first_line: &str, cursor: usize) -> Option<String> {
    let (name, _rest) = command_under_cursor(first_line, cursor)?;
    Some(format!("/{name}"))
}

fn command_under_cursor(first_line: &str, cursor: usize) -> Option<(&str, &str)> {
    if !first_line.starts_with('/') {
        return None;
    }
    if cursor > first_line.len() || !first_line.is_char_boundary(cursor) {
        return None;
    }

    let name_start = 1usize;
    let name_end = first_line[name_start..]
        .find(char::is_whitespace)
        .map(|idx| name_start + idx)
        .unwrap_or_else(|| first_line.len());

    let cursor = if cursor <= name_start {
        name_end
    } else {
        cursor
    };
    if cursor > name_end {
        return None;
    }

    let name = &first_line[name_start..cursor];
    let rest = &first_line[cursor..];

    Some((name, rest))
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct ServiceTierCommand {
    pub(crate) id: String,
    pub(crate) name: String,
    pub(crate) description: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) enum SlashCommandItem {
    Builtin(SlashCommand),
    ServiceTier(ServiceTierCommand),
}

fn add_app_server_stub_message(&mut self, feature: &str) {
        warn!(feature, "stubbed unsupported TUI feature");
        self.add_error_message(format!("{feature}: {TUI_STUB_MESSAGE}"));
    }

pub(crate) fn add_connectors_output(&mut self) {
        if !self.connectors_enabled() {
            self.add_info_message(
                "Apps are disabled.".to_string(),
                Some("Enable the apps feature to use $ or /apps.".to_string()),
            );
            return;
        }

        let connectors_cache = self.connectors.cache.clone();
        let should_force_refetch = !self.connectors.prefetch_in_flight
            || matches!(connectors_cache, ConnectorsCacheState::Ready(_));
        self.queue_connectors_refresh(should_force_refetch);
        self.refresh_connector_mentions(/*force_refresh*/ true);

        match connectors_cache {
            ConnectorsCacheState::Ready(snapshot) => {
                if snapshot.connectors.is_empty() {
                    self.add_info_message("No apps available.".to_string(), /*hint*/ None);
                } else {
                    self.open_connectors_popup(&snapshot.connectors);
                }
            }
            ConnectorsCacheState::Failed(err) => {
                self.add_to_history(history_cell::new_error_event(err));
            }
            ConnectorsCacheState::Loading | ConnectorsCacheState::Uninitialized => {
                self.open_connectors_loading_popup();
            }
        }
        self.request_redraw();
    }

pub(crate) fn add_debug_config_output(&mut self) {
        self.add_to_history(crate::debug_config::new_debug_config_output(
            &self.config,
            self.session_network_proxy.as_ref(),
        ));
    }

