pub(super) fn handle_ide_command(&mut self) {
        if self.ide_context.is_enabled() {
            self.ide_context.disable();
            self.sync_ide_context_status_indicator();
            self.add_info_message("IDE context is off.".to_string(), /*hint*/ None);
        } else {
            self.ide_context.enable();
            self.add_ide_context_status_message();
        }
    }

pub(super) fn handle_ide_command_args(&mut self, args: &str) {
        match args.to_ascii_lowercase().as_str() {
            "" => self.handle_ide_command(),
            "on" => {
                self.ide_context.enable();
                self.add_ide_context_status_message();
            }
            "off" => {
                self.ide_context.disable();
                self.sync_ide_context_status_indicator();
                self.add_info_message("IDE context is off.".to_string(), /*hint*/ None);
            }
            "status" => {
                self.add_ide_context_status_message();
            }
            _ => {
                self.add_error_message("Usage: /ide [on|off|status]".to_string());
            }
        }
    }

pub(super) fn handle_model_command_args(&mut self, args: &str) {
        let command = match resolve_model_command(self, args) {
            Ok(command) => command,
            Err(error) => {
                self.add_error_message(error);
                return;
            }
        };
        let ModelCommand {
            model,
            effort,
            service_tier,
        } = command;
        let warning = self.ultra_reasoning_concurrency_warning(&effort);
        let thread_id = self.sparkle_thread_for_picker_action(&model);
        self.set_queue_autosend_suppressed(/*suppressed*/ true);
        self.app_event_tx.send(
            AstraModelPickerAction::SelectSessionModel {
                effort: Some(effort),
                service_tier,
            }
            .into_picker_event(thread_id, model),
        );
        if let Some(warning) = warning {
            self.add_warning_message(warning);
        }
    }

pub(super) fn handle_status_line_command_args(&mut self, args: &str) {
        let preview_data = self.status_surface_preview_data();
        match parse_status_line_command(args, &preview_data) {
            Ok(command) => {
                if let Some(items) = command.items {
                    let ids = items.iter().map(ToString::to_string).collect::<Vec<_>>();
                    self.status_surface_overrides.status_line = Some(ids.clone());
                    self.local_settings.tui.status_line = Some(ids);
                }
                if let Some(use_theme_colors) = command.use_theme_colors {
                    self.status_surface_overrides.status_line_use_colors = Some(use_theme_colors);
                    self.local_settings.tui.status_line_use_colors = use_theme_colors;
                }
                self.refresh_status_line();
                self.request_redraw();
            }
            Err(error) => self.add_error_message(error),
        }
    }

pub(super) fn handle_terminal_title_command_args(&mut self, args: &str) {
        let preview_data = self.terminal_title_preview_data();
        match parse_terminal_title_command(args, &preview_data) {
            Ok(items) => {
                let ids = items.iter().map(ToString::to_string).collect::<Vec<_>>();
                self.status_surface_overrides.terminal_title = Some(ids.clone());
                self.local_settings.tui.terminal_title = Some(ids);
                self.refresh_terminal_title();
                self.request_redraw();
            }
            Err(error) => self.add_error_message(error),
        }
    }

